BinaryParseVisitor::BinaryParseVisitor(std::span<const u8> f) : file(f) {
    payload = f.size() >= kHeaderSize ? f.subspan(kHeaderSize) : std::span<const u8>{};
}

std::string BinaryParseVisitor::readChars(const char* p, size_t n) {
    size_t len = 0;
    while (len < n && p[len] != 0) ++len;
    return std::string(p, len);
}

bool BinaryParseVisitor::read(Actor& out) {
    const layout::Actor* img = image<layout::Actor>();
    if (!img) return false;
    visit(*img, out);
    return true;
}

